mkdir -p /workspace/probe && cat > /workspace/probe/harness.pl <<'EOF'
use strict; use warnings;
my $BIN='/workspace/dataset/test20_executable';

sub model_under {
  my ($s)=@_; my $o='';
  for my $i (0..length($s)-1) { my $c=substr($s,$i,1);
    if ($c ge 'A' && $c le 'Z') { $o.='_' if $i>0; $o.=lc($c); } else { $o.=$c; } }
  return $o;
}
sub model_dash { my ($s)=@_; $s =~ s/_/-/g; return $s; }

# run binary, return (status, arrayref of 20 lines) -- only valid when input has no LF
sub run {
  my ($s)=@_;
  my $tmp='/tmp/pout.bin';
  open(my $oldout,'>&',\*STDOUT);
  my $pid=open(my $fh,'-|');
  die unless defined $pid;
  if ($pid==0) { open(STDERR,'>','/dev/null'); exec($BIN,$s) or exit 127; }
  local $/; my $out=<$fh>; $out='' unless defined $out; close($fh); my $rc=$?;
  return ($rc,$out);
}

my $probes=0; my @bad;
sub check {
  my ($s,$label)=@_;
  $probes++;
  my ($rc,$out)=run($s);
  if ($rc!=0) { return ('ABORT',$rc,$out); }
  my @L=split(/\n/,$out,-1);
  pop @L if (@L && $L[-1] eq '');
  if (index($s,"\n")>=0) { return ('LF',scalar(@L),$out); }
  if (@L!=20) { push @bad,[$s,$label,'LINECOUNT='.scalar(@L)]; return ('LINECOUNT',scalar(@L),$out); }
  my $eu=model_under($s); my $ed=model_dash($s);
  my $ok=1;
  if ($L[4] ne $eu) { push @bad,[$s,$label,"underscore got=".unpack("H*",$L[4])." exp=".unpack("H*",$eu)]; $ok=0; }
  if ($L[9] ne $ed) { push @bad,[$s,$label,"dasherize got=".unpack("H*",$L[9])." exp=".unpack("H*",$ed)]; $ok=0; }
  return ($ok?'OK':'MISMATCH',$L[4],$L[9]);
}
sub report {
  print "probes=$probes mismatches=".scalar(@bad)."\n";
  for my $b (@bad) { printf("  BAD in=%s (%s) [%s] :: %s\n", unpack("H*",$b->[0]), $b->[0], $b->[1], $b->[2]); }
  @bad=();
}
1;
EOF
